// === Parse ElevenLabs conversation_initiation request + determine clinic ===
// ElevenLabs sends caller_id (phone), agent_id, called_number per docs.

const input = $input.first();
const body = input.json.body || input.json || {};

// Extract caller phone — ElevenLabs may use various keys depending on source (Twilio, SIP, widget)
let phone = body.caller_id || body.from || body.From || body.phone_number || '';
if (typeof phone !== 'string') phone = String(phone);
phone = phone.trim();

const agentId = body.agent_id || body.agentId || body.AgentId || '';

// Map agent_id → clinic identity
const CLINIC_MAP = {
  'agent_9601kr2e38r2f2btyjkyxtzearzh': {
    clinic_location: 'Little Haiti',
    location_id: 'ovwnwONQoTtdloXHe18w',
    pit_token: 'pit-79343142-2606-4e77-9ab7-ccdd74a3cfb3',
  },
  'agent_1601kr6f47whfhq9yjj31e1epn6e': {
    clinic_location: 'North Miami',
    location_id: 'GtIT2mC9PzORGf4M1unB',
    pit_token: 'pit-6153670b-6d28-4b27-823e-d4487e5ad49d',
  },
};
const clinic = CLINIC_MAP[agentId] || { clinic_location: 'Unknown', location_id: '', pit_token: '' };

// Compute is_after_hours: Mon-Fri 8 AM - 5 PM Miami time = OPEN; else AFTER-HOURS
const TZ = 'America/New_York';
const now = new Date();
const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, weekday: 'short', hour: 'numeric', hour12: false, year: 'numeric', month: 'numeric', day: 'numeric'
});
const parts = fmt.formatToParts(now);
const partMap = Object.fromEntries(parts.map(p => [p.type, p.value]));
const weekday = partMap.weekday;
const hour = parseInt(partMap.hour, 10);
const isWeekday = ['Mon','Tue','Wed','Thu','Fri'].includes(weekday);
const inHours = isWeekday && hour >= 8 && hour < 17;
const isAfterHours = !inHours;


// === Current date in Miami time (Creole + ISO) ===
const dateFmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const currentDateIso = dateFmt.format(now); // YYYY-MM-DD
const CREOLE_DAYS = { Mon: 'lendi', Tue: 'madi', Wed: 'mèkredi', Thu: 'jedi', Fri: 'vandredi', Sat: 'samdi', Sun: 'dimanch' };
const CREOLE_MONTHS = ['janvye','fevriye','mas','avril','me','jen','jiyè','out','septanm','oktòb','novanm','desanm'];
const dayNum = parseInt(partMap.day, 10);
const monthIdx = parseInt(partMap.month, 10) - 1;
const yearNum = partMap.year;
const currentDateCreole = `${CREOLE_DAYS[weekday] || weekday} ${dayNum} ${CREOLE_MONTHS[monthIdx] || ''} ${yearNum}`;

return [{
  json: {
    phone,
    agent_id: agentId,
    clinic_location: clinic.clinic_location,
    location_id: clinic.location_id,
    pit_token: clinic.pit_token,
    is_after_hours: isAfterHours ? 'true' : 'false',
    timezone: TZ,
    current_date_iso: currentDateIso,
    current_date_creole: currentDateCreole,
    miami_time_debug: `${weekday} ${hour}:00`,
    raw_body_keys: Object.keys(body),
  }
}];

// === Assemble conversation_initiation_client_data — Redis memory PRIMARY, GHL fallback ===
const ctx = $('Determine Clinic + Time').item.json;

// Redis profile (JSON string) — may be empty for a new patient
let mem = {};
try {
  const raw = $('Redis Get Profile').item.json.redisProfileRaw;
  if (raw && typeof raw === 'string') mem = JSON.parse(raw);
  else if (raw && typeof raw === 'object') mem = raw;
} catch (e) { mem = {}; }

// GHL contact (fallback / enrichment)
const ghl = $input.first().json || {};
const contacts = ghl.contacts || [];
const c = contacts.length > 0 ? contacts[0] : {};

// Merge: Redis wins, then GHL, then blank
const firstName = mem.first_name || c.firstName || c.first_name || '';
const lastName  = mem.last_name  || c.lastName  || c.last_name  || '';
const phone     = mem.caller_phone || ctx.phone || c.phone || '';

const isReturning = !!(mem.first_name);  // we have a stored profile = returning patient

return [{
  json: {
    type: 'conversation_initiation_client_data',
    dynamic_variables: {
      // identity
      caller_first_name: firstName,
      caller_last_name: lastName,
      caller_phone: phone,
      // clinic + timing
      is_after_hours: ctx.is_after_hours,
      clinic_location: ctx.clinic_location,
      location_id: ctx.location_id,
      ghl_pit_token: ctx.pit_token,
      timezone: ctx.timezone,
      current_date_iso: ctx.current_date_iso || '',
      current_date_creole: ctx.current_date_creole || '',
      // === MEMORY (from Redis) ===
      is_returning_patient: isReturning ? 'true' : 'false',
      patient_dob: mem.dob || '',
      patient_insurance: mem.insurance_plan || '',
      patient_insurance_verified: mem.insurance_verified || '',
      patient_pharmacy: mem.preferred_pharmacy || '',
      patient_medications: mem.known_medications || '',
      last_call_reason: mem.last_call_reason || '',
      last_call_date: mem.last_call_date || '',
      last_call_summary: mem.last_call_summary || '',
    }
  }
}];

